// 注意：这个函数会修改原字符串 s
int valid(char s[]) {
    int n = 0;
    while (s[n] != '\0') n++;  // 手动求字符串长度

    while (n >= 2) {
        int found = 0;         // 这一轮有没有删掉一对

        for (int i = 0; i < n - 1; i++) {
            if (match(s[i], s[i + 1])) {
                // 把后面的字符左移2位，包括结束符'\0'
